		t.Run(tc.Input+"/"+tc.Label, func(t *testing.T) {
			list, doc := completionFor(tc.Input, tc.Options)
			assertUniqueCompletionLabels(t, list)
			if tc.Count != nil {
				if got := len(list.Items); got != *tc.Count {
					t.Fatalf("completion count: got %d want %d; items=%#v", got, *tc.Count, list.Items)
				}
				return
			}
			if tc.NotAvailable {
				assertNoCompletion(t, list, tc.Label)
				return
			}
			item := mustCompletion(t, list, tc.Label)
			if tc.ResultText != "" {
				assertCompletionApplies(t, list, doc, tc.Label, tc.ResultText)
			}
			if tc.FilterText != "" && item.FilterText != tc.FilterText {
				t.Fatalf("filterText for %s: got %q want %q", tc.Label, item.FilterText, tc.FilterText)
			}
			if tc.Documentation {
				assertDocumentationValue(t, item, "The div element has no special meaning at all. It represents its children. It can be used with the class, lang, and title attributes to mark up semantics common to a group of consecutive elements.\n\n![Baseline icon]("+baselineHighImage+") _Widely available across major browsers (Baseline since 2015)_\n\n[MDN Reference](https://developer.mozilla.org/docs/Web/HTML/Reference/Elements/div)")
			}
		})
